package com.UnsiredTracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("unsiredtracker")
public interface UnsiredTrackerConfig extends Config
{
	@ConfigSection(
			name = "Display Settings",
			description = "Choose which stats are shown on the overlay.",
			position = 0
	)
	String displaySection = "displaySection";

	@ConfigSection(
			name = "Setup Settings",
			description = "Configure baseline values.",
			position = 1
	)
	String setupSection = "setupSection";

	@ConfigItem(
			keyName = "currentKC",
			name = "Current KC",
			description = "Show current Abyssal Sire kill count.",
			section = displaySection,
			position = 0
	)
	default boolean currentKC()
	{
		return true;
	}

    /*
    @ConfigItem( // CAN USE THIS FOR TESTING PURPOSES
            keyName = "simulateUnsiredDrop",
            name = "Simulate Unsired Drop",
            description = "Testing only: simulate receiving an Unsired drop using your current KC.",
            section = setupSection
    )
    default boolean simulateUnsiredDrop()
    {
        return false;
    }
    */

	@ConfigItem(
			keyName = "lastUnsiredKC",
			name = "Last Unsired KC",
			description = "Show the kill count of your most recent Unsired.",
			section = displaySection,
			position = 1
	)
	default boolean lastUnsiredKC()
	{
		return true;
	}

	@ConfigItem(
			keyName = "killsSinceLastUnsired",
			name = "Current Dry",
			description = "Show kills since your last Unsired.",
			section = displaySection,
			position = 2
	)
	default boolean killsSinceLastUnsired()
	{
		return true;
	}

	@ConfigItem(
			keyName = "lastDry",
			name = "Last Dry",
			description = "Show how many kills it took to get your most recent Unsired.",
			section = displaySection,
			position = 3
	)
	default boolean lastDry()
	{
		return true;
	}

	@ConfigItem(
			keyName = "dryStreak",
			name = "Longest Dry",
			description = "Highest number of kills between Unsired drops.",
			section = displaySection,
			position = 4
	)
	default boolean dryStreak()
	{
		return true;
	}

	@ConfigItem(
			keyName = "bestStreak",
			name = "Most Spooned",
			description = "Lowest number of kills between Unsired drops.",
			section = displaySection,
			position = 5
	)
	default boolean bestStreak()
	{
		return true;
	}

	@ConfigItem(
			keyName = "baselineUnsiredKC",
			name = "Last Unsired KC",
			description = "Used to establish your last known Unsired KC. If unknown, do nothing.",
			section = setupSection,
			position = 0
	)
	default int baselineUnsiredKC()
	{
		return 0;
	}

	@ConfigItem(
			keyName = "applyBaselineKC",
			name = "Apply KC of last unsired",
			description = "Check the box to set the value of 'Last Unsired KC' for the plugin.",
			section = setupSection,
			position = 1
	)
	default boolean applyBaselineKC()
	{
		return false;
	}
}

package com.UnsiredTracker;

import net.runelite.api.MenuAction;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayMenuEntry;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;

import javax.inject.Inject;
import java.awt.*;

public class UnsiredTrackerOverlay extends Overlay
{
    private final UnsiredTrackerPlugin plugin;
    private final PanelComponent panelComponent = new PanelComponent();

    @Inject
    public UnsiredTrackerOverlay(UnsiredTrackerPlugin plugin)
    {
        this.plugin = plugin;

        setPosition(OverlayPosition.TOP_LEFT);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(OverlayPriority.HIGH);

        getMenuEntries().add(
                new OverlayMenuEntry(
                        MenuAction.RUNELITE_OVERLAY,
                        "Reset",
                        "All Stats"
                ));

        getMenuEntries().add(
                new OverlayMenuEntry(
                        MenuAction.RUNELITE_OVERLAY,
                        "Reset",
                        "Last Unsired KC"
                ));

        getMenuEntries().add(
                new OverlayMenuEntry(
                        MenuAction.RUNELITE_OVERLAY,
                        "Reset",
                        "Longest Dry"
                ));

        getMenuEntries().add(
                new OverlayMenuEntry(
                        MenuAction.RUNELITE_OVERLAY,
                        "Reset",
                        "Most Spooned"
                ));
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        panelComponent.getChildren().clear();

        if (plugin.getConfig().currentKC())
        {
            panelComponent.getChildren().add(
                    LineComponent.builder()
                            .left("Current KC")
                            .right(String.valueOf(plugin.getCurrentSireKC()))
                            .build()
            );
        }

        if (plugin.getConfig().lastUnsiredKC())
        {
            panelComponent.getChildren().add(
                    LineComponent.builder()
                            .left("Last Unsired")
                            .right(String.valueOf(plugin.getLastUnsiredKC()))
                            .build()
            );
        }

        if (plugin.getConfig().killsSinceLastUnsired())
        {
            panelComponent.getChildren().add(
                    LineComponent.builder()
                            .left("Current Dry")
                            .right(String.valueOf(plugin.getKillsSinceLastUnsired()))
                            .build()
            );
        }

        if (plugin.getConfig().lastDry())
        {
            panelComponent.getChildren().add(
                    LineComponent.builder()
                            .left("Last Dry")
                            .right(String.valueOf(plugin.getLastDry()))
                            .build()
            );
        }

        if (plugin.getConfig().dryStreak())
        {
            panelComponent.getChildren().add(
                    LineComponent.builder()
                            .left("Longest Dry")
                            .right(String.valueOf(plugin.getDryStreak()))
                            .build()
            );
        }

        if (plugin.getConfig().bestStreak())
        {
            panelComponent.getChildren().add(
                    LineComponent.builder()
                            .left("Most Spooned")
                            .right(String.valueOf(plugin.getBestStreak()))
                            .build()
            );
        }

        return panelComponent.render(graphics);
    }
}

package com.UnsiredTracker;

import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.OverlayMenuClicked;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Slf4j
@PluginDescriptor(
		name = "Unsired Tracker"
)
public class UnsiredTrackerPlugin extends Plugin
{
	private static final String CONFIG_GROUP = "unsiredtracker";

	private static final Set<Integer> ABYSSAL_NEXUS_REGIONS = Set.of(
			11850,
			11851,
			12106,
			12362,
			12363
	);

	private static final Pattern KC_PATTERN =
			Pattern.compile("Your Abyssal Sire kill count is: ([\\d,]+)");

	private static final String UNSIRED_DROP_MESSAGE =
			"<col=ef1020>Untradeable drop: Unsired</col>";

	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private UnsiredTrackerOverlay overlay;

	@Inject
	private ConfigManager configManager;

	@Inject
	private UnsiredTrackerConfig config;

	private boolean overlayAdded = false;

	private int currentSireKC;
	private int killsSinceLastUnsired;
	private int lastDry;
	private int lastUnsiredKC;
	private int dryStreak;
	private int bestStreak;

	@Override
	protected void startUp()
	{
		loadProfileData();
	}

	@Override
	protected void shutDown()
	{
		saveAllStats();

		overlayManager.remove(overlay);
		overlayAdded = false;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			loadProfileData();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Player player = client.getLocalPlayer();

		if (player == null)
		{
			return;
		}

		WorldPoint location = player.getWorldLocation();

		if (location == null)
		{
			return;
		}

		boolean validRegion =
				ABYSSAL_NEXUS_REGIONS.contains(location.getRegionID());

		if (validRegion && !overlayAdded)
		{
			overlayManager.add(overlay);
			overlayAdded = true;
		}
		else if (!validRegion && overlayAdded)
		{
			overlayManager.remove(overlay);
			overlayAdded = false;
		}
	}

	@Subscribe
	public void onOverlayMenuClicked(OverlayMenuClicked event)
	{
		if (event.getOverlay() != overlay)
		{
			return;
		}

		String option = event.getEntry().getOption();
		String target = event.getEntry().getTarget();

		if (!option.equals("Reset"))
		{
			return;
		}

		switch (target)
		{
			case "All Stats":
				resetAllStats();
				break;

			case "Last Unsired KC":
				resetLastUnsiredKC();
				break;

			case "Longest Dry":
				resetDryStreak();
				break;

			case "Most Spooned":
				resetBestStreak();
				break;
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CONFIG_GROUP.equals(event.getGroup()))
		{
			return;
		}

		if (config.applyBaselineKC())
		{
			lastUnsiredKC = config.baselineUnsiredKC();

			recalculateKillsSinceLastUnsired();

			saveAllStats();

			configManager.setConfiguration(
					CONFIG_GROUP,
					"applyBaselineKC",
					false
			);

            /*
            log.debug(
                    "Applied baseline KC {}. Current KC: {}. Current dry: {}",
                    lastUnsiredKC,
                    currentSireKC,
                    killsSinceLastUnsired
            );
            */
		}

        /*
        // CAN USE THIS FOR TESTING PURPOSES
        // Only uncomment this if simulateUnsiredDrop() exists in UnsiredTrackerConfig.
        if (config.simulateUnsiredDrop())
        {
            handleUnsiredDrop();

            configManager.setConfiguration(
                    CONFIG_GROUP,
                    "simulateUnsiredDrop",
                    false
            );

            log.info(
                    "Simulated Unsired drop at KC {}. Last Unsired KC: {}. Current Dry: {}. Last Dry: {}. Longest Dry: {}. Most Spooned: {}",
                    currentSireKC,
                    lastUnsiredKC,
                    killsSinceLastUnsired,
                    lastDry,
                    dryStreak,
                    bestStreak
            );
        }
        */
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		String message = event.getMessage();
		String cleanMessage = Text.removeTags(message);

		// Temporary testing logs. Use info, not debug, so they show in IntelliJ.
		//log.info("CHAT RAW: {}", message);
		//log.info("CHAT CLEAN: {}", cleanMessage);

		Matcher matcher = KC_PATTERN.matcher(cleanMessage);

		if (matcher.find())
		{
			currentSireKC = Integer.parseInt(
					matcher.group(1)
							.replace(",", "")
							.trim()
			);

			recalculateKillsSinceLastUnsired();

			saveCurrentStats();

			//log.info("Updated Abyssal Sire KC to {}", currentSireKC);
			return;
		}

		if (message.equals(UNSIRED_DROP_MESSAGE))
		{
			handleUnsiredDrop();
		}
	}

	private void recalculateKillsSinceLastUnsired()
	{
		if (currentSireKC > 0 && lastUnsiredKC > 0 && currentSireKC >= lastUnsiredKC)
		{
			killsSinceLastUnsired = currentSireKC - lastUnsiredKC;
		}
		else
		{
			killsSinceLastUnsired = 0;
		}
	}

	private void handleUnsiredDrop()
	{
		if (currentSireKC <= 0)
		{
			log.debug("Unsired received, but current Sire KC is unknown. Drop ignored.");
			return;
		}

		if (lastUnsiredKC > 0)
		{
			int gap = currentSireKC - lastUnsiredKC;

			if (gap > 0)
			{
				lastDry = gap;

				if (gap > dryStreak)
				{
					dryStreak = gap;
				}

				if (bestStreak == 0 || gap < bestStreak)
				{
					bestStreak = gap;
				}
			}
		}

		lastUnsiredKC = currentSireKC;
		killsSinceLastUnsired = 0;

		saveAllStats();

		//log.debug("Unsired received at KC {}. Last dry: {}", currentSireKC, lastDry);
	}

	private void loadProfileData()
	{
		Integer savedCurrentKC =
				configManager.getRSProfileConfiguration(
						CONFIG_GROUP,
						"currentSireKC",
						Integer.class
				);

		Integer savedKillsSince =
				configManager.getRSProfileConfiguration(
						CONFIG_GROUP,
						"killsSinceLastUnsired",
						Integer.class
				);

		Integer savedLastUnsired =
				configManager.getRSProfileConfiguration(
						CONFIG_GROUP,
						"lastUnsiredKC",
						Integer.class
				);

		Integer savedLastDry =
				configManager.getRSProfileConfiguration(
						CONFIG_GROUP,
						"lastDry",
						Integer.class
				);

		Integer savedDry =
				configManager.getRSProfileConfiguration(
						CONFIG_GROUP,
						"dryStreak",
						Integer.class
				);

		Integer savedBest =
				configManager.getRSProfileConfiguration(
						CONFIG_GROUP,
						"bestStreak",
						Integer.class
				);

		currentSireKC = savedCurrentKC == null ? 0 : savedCurrentKC;
		killsSinceLastUnsired = savedKillsSince == null ? 0 : savedKillsSince;
		lastUnsiredKC = savedLastUnsired == null ? 0 : savedLastUnsired;
		lastDry = savedLastDry == null ? 0 : savedLastDry;
		dryStreak = savedDry == null ? 0 : savedDry;
		bestStreak = savedBest == null ? 0 : savedBest;
	}

	private void saveCurrentStats()
	{
		configManager.setRSProfileConfiguration(
				CONFIG_GROUP,
				"currentSireKC",
				currentSireKC
		);

		configManager.setRSProfileConfiguration(
				CONFIG_GROUP,
				"killsSinceLastUnsired",
				killsSinceLastUnsired
		);
	}

	private void saveAllStats()
	{
		configManager.setRSProfileConfiguration(
				CONFIG_GROUP,
				"currentSireKC",
				currentSireKC
		);

		configManager.setRSProfileConfiguration(
				CONFIG_GROUP,
				"killsSinceLastUnsired",
				killsSinceLastUnsired
		);

		configManager.setRSProfileConfiguration(
				CONFIG_GROUP,
				"lastUnsiredKC",
				lastUnsiredKC
		);

		configManager.setRSProfileConfiguration(
				CONFIG_GROUP,
				"lastDry",
				lastDry
		);

		configManager.setRSProfileConfiguration(
				CONFIG_GROUP,
				"dryStreak",
				dryStreak
		);

		configManager.setRSProfileConfiguration(
				CONFIG_GROUP,
				"bestStreak",
				bestStreak
		);
	}

	public void resetAllStats()
	{
		currentSireKC = 0;
		killsSinceLastUnsired = 0;
		lastUnsiredKC = 0;
		lastDry = 0;
		dryStreak = 0;
		bestStreak = 0;

		saveAllStats();
	}

	public void resetLastUnsiredKC()
	{
		lastUnsiredKC = 0;
		killsSinceLastUnsired = 0;

		configManager.setRSProfileConfiguration(
				CONFIG_GROUP,
				"lastUnsiredKC",
				lastUnsiredKC
		);

		configManager.setRSProfileConfiguration(
				CONFIG_GROUP,
				"killsSinceLastUnsired",
				killsSinceLastUnsired
		);
	}

	public void resetDryStreak()
	{
		dryStreak = 0;

		configManager.setRSProfileConfiguration(
				CONFIG_GROUP,
				"dryStreak",
				dryStreak
		);
	}

	public void resetBestStreak()
	{
		bestStreak = 0;

		configManager.setRSProfileConfiguration(
				CONFIG_GROUP,
				"bestStreak",
				bestStreak
		);
	}

	@Provides
	UnsiredTrackerConfig provideConfig()
	{
		return configManager.getConfig(
				UnsiredTrackerConfig.class
		);
	}

	public UnsiredTrackerConfig getConfig()
	{
		return config;
	}

	public int getCurrentSireKC()
	{
		return currentSireKC;
	}

	public int getLastUnsiredKC()
	{
		return lastUnsiredKC;
	}

	public int getKillsSinceLastUnsired()
	{
		return killsSinceLastUnsired;
	}

	public int getLastDry()
	{
		return lastDry;
	}

	public int getDryStreak()
	{
		return dryStreak;
	}

	public int getBestStreak()
	{
		return bestStreak;
	}
}
